args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { dbr:Hidden_Power dbr:Hiawanda's_Cross }
  # director may be stored in dbo:director or dbp:director
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director (dbo:deathDate|dbp:deathDate) ?deathDate . }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
}

